// Turns a server's tools/list into a TypeScript module: one type per tool's input schema,
// plus a hash of each schema so the runtime can refuse tools whose schema has drifted.

use serde_json::Value;
use sha2::{Digest, Sha256};
use std::fmt::Write;

pub fn module(server: &str, tools: &[Value]) -> String {
    let ident = pascal(server);
    let mut out = format!(
        "// Generated by `complier gen {server}`. Do not edit.\n\nexport type {ident}Tools = {{\n"
    );
    let mut hashes = String::new();
    for tool in tools {
        let name = tool["name"].as_str().unwrap_or_default();
        let schema = &tool["inputSchema"];
        if let Some(description) = tool["description"].as_str() {
            doc(&mut out, description, 1);
        }
        let _ = writeln!(out, "  {}: {};", key(name), ty(schema, 1));
        let _ = writeln!(hashes, "  {}: \"{}\",", key(name), hash(schema));
    }
    let camel = ident[..1].to_lowercase() + &ident[1..];
    let _ = write!(out, "}};\n\nexport const {camel}SchemaHashes = {{\n{hashes}}} as const;\n");
    out
}

// sha256 of the schema's canonical JSON (serde_json orders object keys).
pub fn hash(schema: &Value) -> String {
    Sha256::digest(schema.to_string().as_bytes())
        .iter()
        .take(8)
        .map(|b| format!("{b:02x}"))
        .collect()
}

// JSON Schema to a TypeScript type. Anything it doesn't understand becomes `unknown`.
fn ty(schema: &Value, depth: usize) -> String {
    if let Some(value) = schema.get("const") {
        return value.to_string();
    }
    if let Some(values) = schema["enum"].as_array() {
        return union(values.iter().map(Value::to_string));
    }
    for key in ["anyOf", "oneOf"] {
        if let Some(variants) = schema[key].as_array() {
            return union(variants.iter().map(|v| ty(v, depth)));
        }
    }
    if let Some(parts) = schema["allOf"].as_array() {
        return parts.iter().map(|p| ty(p, depth)).collect::<Vec<_>>().join(" & ");
    }
    match &schema["type"] {
        Value::Array(types) => union(types.iter().map(|t| {
            let mut single = schema.clone();
            single["type"] = t.clone();
            ty(&single, depth)
        })),
        Value::String(t) => match t.as_str() {
            "string" => "string".into(),
            "number" | "integer" => "number".into(),
            "boolean" => "boolean".into(),
            "null" => "null".into(),
            "array" => match schema.get("items") {
                Some(items) => format!("Array<{}>", ty(items, depth)),
                None => "unknown[]".into(),
            },
            "object" => object(schema, depth),
            _ => "unknown".into(),
        },
        _ if schema.get("properties").is_some() => object(schema, depth),
        _ => "unknown".into(),
    }
}

fn object(schema: &Value, depth: usize) -> String {
    let Some(properties) = schema["properties"].as_object().filter(|p| !p.is_empty()) else {
        return match &schema["additionalProperties"] {
            Value::Bool(false) => "Record<string, never>".into(),
            Value::Object(_) => format!("Record<string, {}>", ty(&schema["additionalProperties"], depth)),
            _ => "Record<string, unknown>".into(),
        };
    };
    let required: Vec<&str> = schema["required"]
        .as_array()
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let indent = "  ".repeat(depth + 1);
    let mut out = String::from("{\n");
    for (name, property) in properties {
        if let Some(description) = property["description"].as_str() {
            doc(&mut out, description, depth + 1);
        }
        let optional = if required.contains(&name.as_str()) { "" } else { "?" };
        let _ = writeln!(out, "{indent}{}{optional}: {};", key(name), ty(property, depth + 1));
    }
    out + &"  ".repeat(depth) + "}"
}

fn union(members: impl Iterator<Item = String>) -> String {
    let mut members: Vec<String> = members.collect();
    members.dedup();
    if members.is_empty() { "never".into() } else { members.join(" | ") }
}

fn doc(out: &mut String, text: &str, depth: usize) {
    let indent = "  ".repeat(depth);
    let _ = writeln!(out, "{indent}/**");
    for line in text.trim().lines() {
        let _ = writeln!(out, "{indent} * {}", line.replace("*/", "*\\/"));
    }
    let _ = writeln!(out, "{indent} */");
}

fn key(name: &str) -> String {
    let identifier = name.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
        && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$');
    if identifier { name.to_string() } else { Value::String(name.into()).to_string() }
}

fn pascal(name: &str) -> String {
    name.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
        .map(|w| w[..1].to_uppercase() + &w[1..])
        .collect()
}
